=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none
// skid_buffer: two-register valid/ready slice (register slice).
// Implements microarchitecture.md section 3; ports per interface_spec.md.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Next-state signals.
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             m_load;
    reg             skid_valid_d;
    reg             skid_load;

    wire m_free;
    wire s_fire;

    assign s_ready = !skid_valid;              // inverter after a flop
    assign m_free  = !m_valid || m_ready;      // output register may load
    assign s_fire  = s_valid && s_ready;       // upstream transfer

    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = s_data;
        m_load       = 1'b0;
        skid_valid_d = skid_valid;
        skid_load    = 1'b0;
        if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output; s_ready is low, so no input beat.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                m_load       = 1'b1;
                skid_valid_d = 1'b0;
            end else begin
                // Output register takes the input directly.
                m_valid_d    = s_valid;
                m_data_d     = s_data;
                m_load       = 1'b1;
            end
        end else if (s_fire) begin
            // Output stalled, beat accepted: it goes to the skid register.
            skid_valid_d = 1'b1;
            skid_load    = 1'b1;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture.md section 2).
    always @(posedge clk) begin
        if (m_load) begin
            m_data <= m_data_d;
        end
        if (skid_load) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent properties (not proven in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
        if (skid_valid) assert(m_valid);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if ($past(!rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end else if ($past(m_valid && !m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
                if ($past(skid_valid)) begin
                    assert(skid_valid);
                    assert(skid_data == $past(skid_data));
                end
            end
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
