`timescale 1ns/1ps
`default_nettype none
// Self-checking testbench for skid_buffer: lanes at WIDTH 8 and WIDTH 1.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) u_w8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8)
    );

    skid_buffer #(.WIDTH(1)) u_w1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data[0:0]),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    // Bookkeeping.
    integer passed;
    integer failed;
    integer count;
    integer total_in;
    integer total_out;
    integer total_drop;
    integer cov_full;
    integer cov_stall1;
    integer cov_flow;
    integer i;
    integer k;
    integer thr_s;
    integer thr_m;
    reg [7:0]  mq0, mq1, mq2;
    reg        model_known;
    reg        hold_pending;
    reg [7:0]  hold_data;
    reg        up_fire;
    reg        dn_fire;
    reg        sr8_s, sr1_s, mv8_s, mv1_s;
    reg [7:0]  md8_s;
    reg        md1_s;
    reg        sv_r, mr_r;
    reg [7:0]  seq;
    reg [31:0] rng;
    reg [8*64-1:0] nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task rand_step;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check;
        input            cond;
        input [8*48-1:0] what;
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL: %0s at time %0t", what, $time);
            end
        end
    endtask

    // One clock cycle. Called just after a falling edge; returns at the next one.
    task cycle;
        input       sv;
        input [7:0] sd;
        input       mr;
        begin
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            #1;
            if (model_known) begin
                if (hold_pending) begin
                    check(m_valid8 === 1'b1 && m_data8 === hold_data, "hold: stalled beat unchanged (w8)");
                    check(m_valid1 === 1'b1 && m_data1 === hold_data[0:0], "hold: stalled beat unchanged (w1)");
                end
                check(m_valid8 === (count != 0), "m_valid matches model (w8)");
                check(m_valid1 === (count != 0), "m_valid matches model (w1)");
                check(s_ready8 === (count < 2), "s_ready matches model (w8)");
                check(s_ready1 === (count < 2), "s_ready matches model (w1)");
                if (count != 0) begin
                    check(m_data8 === mq0, "m_data is oldest beat (w8)");
                    check(m_data1 === mq0[0:0], "m_data is oldest beat (w1)");
                end
            end
            hold_pending = 1'b0;

            // Outputs must not move with inputs inside a cycle.
            sr8_s = s_ready8; sr1_s = s_ready1;
            mv8_s = m_valid8; mv1_s = m_valid1;
            md8_s = m_data8;  md1_s = m_data1[0];
            s_valid = ~sv;
            m_ready = ~mr;
            s_data  = ~sd;
            #1;
            if (model_known) begin
                check(s_ready8 === sr8_s && s_ready1 === sr1_s, "s_ready independent of inputs in cycle");
                check(m_valid8 === mv8_s && m_valid1 === mv1_s, "m_valid independent of inputs in cycle");
                check(m_data8 === md8_s && m_data1[0] === md1_s, "m_data independent of inputs in cycle");
            end
            s_valid = sv;
            m_ready = mr;
            s_data  = sd;
            #1;

            up_fire = rst_n && s_valid && s_ready8;
            dn_fire = rst_n && m_valid8 && m_ready;
            if (model_known && rst_n) begin
                if (m_valid8 && !m_ready) begin
                    hold_pending = 1'b1;
                    hold_data    = m_data8;
                end
                if (count == 2) cov_full = cov_full + 1;
                if (count == 1 && !m_ready && s_valid) cov_stall1 = cov_stall1 + 1;
                if (up_fire && dn_fire) cov_flow = cov_flow + 1;
            end

            @(posedge clk);
            if (!rst_n) begin
                if (model_known) total_drop = total_drop + count;
                count        = 0;
                model_known  = 1'b1;
                hold_pending = 1'b0;
            end else begin
                if (dn_fire) begin
                    total_out = total_out + 1;
                    mq0 = mq1;
                    mq1 = mq2;
                    count = count - 1;
                end
                if (up_fire) begin
                    total_in = total_in + 1;
                    if (count == 0)      mq0 = sd;
                    else if (count == 1) mq1 = sd;
                    else                 mq2 = sd;
                    count = count + 1;
                end
                check(count >= 0 && count <= 2, "model holds zero to two beats");
            end
            @(negedge clk);
        end
    endtask

    task reset_cycles;
        input integer n;
        begin
            rst_n = 1'b0;
            for (k = 0; k < n; k = k + 1) begin
                rand_step;
                cycle(rng[0], rng[15:8], rng[1]);
            end
            rst_n = 1'b1;
            check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low");
            check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high");
        end
    endtask

    initial begin
        passed = 0; failed = 0; count = 0;
        total_in = 0; total_out = 0; total_drop = 0;
        cov_full = 0; cov_stall1 = 0; cov_flow = 0;
        mq0 = 8'h00; mq1 = 8'h00; mq2 = 8'h00;
        model_known = 1'b0; hold_pending = 1'b0; hold_data = 8'h00;
        up_fire = 1'b0; dn_fire = 1'b0;
        rng = 32'h1234_5678;
        rst_n = 1'b0; s_valid = 1'b0; s_data = 8'h00; m_ready = 1'b0;
        seq = 8'h00;
        @(negedge clk);

        // 1. Reset values.
        reset_cycles(2);

        // 2. One-cycle latency.
        check(m_valid8 === 1'b0, "latency: empty before beat");
        cycle(1'b1, 8'hA5, 1'b1);
        check(up_fire === 1'b1, "latency: beat accepted");
        check(m_valid8 === 1'b1 && m_data8 === 8'hA5, "latency: offered after accept (w8)");
        check(m_valid1 === 1'b1 && m_data1 === 1'b1, "latency: offered after accept (w1)");
        cycle(1'b0, 8'h00, 1'b1);
        check(dn_fire === 1'b1, "latency: beat taken");
        check(m_valid8 === 1'b0, "latency: empty after beat leaves");

        // 3. Full throughput, counting data.
        seq = 8'h00;
        for (i = 0; i < 40; i = i + 1) begin
            cycle(1'b1, seq, 1'b1);
            check(up_fire === 1'b1, "throughput: beat in every cycle");
            if (i > 0) check(dn_fire === 1'b1, "throughput: beat out every cycle");
            seq = seq + 8'd1;
        end
        cycle(1'b0, 8'h00, 1'b1);
        check(dn_fire === 1'b1, "throughput: last beat out");
        cycle(1'b0, 8'h00, 1'b1);
        check(m_valid8 === 1'b0 && s_ready8 === 1'b1, "throughput: idle after stream");

        // 4. Stall with one beat held, then two; ready rising.
        cycle(1'b1, 8'h10, 1'b0);
        check(up_fire === 1'b1, "stall: first beat accepted");
        cycle(1'b1, 8'h11, 1'b0);
        check(up_fire === 1'b1, "stall: second beat accepted, one held");
        cycle(1'b1, 8'h12, 1'b0);
        check(up_fire === 1'b0, "stall: third beat refused, two held");
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 8'h12, 1'b0);
            check(up_fire === 1'b0 && m_data8 === 8'h10, "stall: full slice holds");
        end
        cycle(1'b1, 8'h12, 1'b1);
        check(dn_fire === 1'b1 && up_fire === 1'b0, "ready rise: oldest out, none in");
        cycle(1'b1, 8'h12, 1'b1);
        check(dn_fire === 1'b1 && up_fire === 1'b1, "ready rise: second out, third in");
        cycle(1'b0, 8'h00, 1'b1);
        check(dn_fire === 1'b1, "ready rise: third out");
        cycle(1'b0, 8'h00, 1'b1);
        check(dn_fire === 1'b0 && m_valid8 === 1'b0 && s_ready8 === 1'b1, "ready rise: idle after drain");

        // 5. Single-cycle stall inside a stream.
        cycle(1'b1, 8'h20, 1'b1);
        cycle(1'b1, 8'h21, 1'b0);
        check(up_fire === 1'b1 && dn_fire === 1'b0, "short stall: beat skids");
        cycle(1'b1, 8'h22, 1'b1);
        check(up_fire === 1'b0 && dn_fire === 1'b1, "short stall: full, drains");
        cycle(1'b1, 8'h22, 1'b1);
        check(up_fire === 1'b1 && dn_fire === 1'b1, "short stall: flow resumes");
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        check(m_valid8 === 1'b0, "short stall: idle");

        // 6. Reset with two beats held.
        cycle(1'b1, 8'h30, 1'b0);
        cycle(1'b1, 8'h31, 1'b0);
        check(s_ready8 === 1'b0 && m_valid8 === 1'b1, "reset-held: two beats before reset");
        reset_cycles(1);
        cycle(1'b1, 8'h3C, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        check(dn_fire === 1'b1, "reset-held: new beat out after reset");
        cycle(1'b0, 8'h00, 1'b1);
        check(m_valid8 === 1'b0, "reset-held: only the new beat came out");

        // 7. Random traffic against the model, with resets in the last phase.
        for (i = 0; i < 4000; i = i + 1) begin
            rand_step;
            if (i < 1000)      begin thr_s = 128; thr_m = 128; end
            else if (i < 2000) begin thr_s = 230; thr_m = 70;  end
            else if (i < 3000) begin thr_s = 70;  thr_m = 230; end
            else               begin thr_s = 160; thr_m = 160; end
            sv_r = (rng[7:0]  < thr_s);
            mr_r = (rng[15:8] < thr_m);
            if (i >= 3000 && rng[30:24] == 7'd0) rst_n = 1'b0;
            cycle(sv_r, rng[23:16], mr_r);
            rst_n = 1'b1;
        end

        // 8. Drain.
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b0, 8'h00, 1'b1);
        end
        check(count == 0, "drain: model empty");
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "drain: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "drain: s_ready high");
        check(total_in == total_out + total_drop, "every accepted beat out once or dropped by reset");
        check(cov_full > 0, "coverage: full slice reached");
        check(cov_stall1 > 0, "coverage: stall with one beat reached");
        check(cov_flow > 0, "coverage: simultaneous in and out reached");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
`default_nettype wire
=== END FILE ===
